// Sections generated by Layer8SectionGenerator: Tunnels, Access, Edge and
// Alerts. Each is one module (tab) whose services are the sub-navigation.
(function() {
    'use strict';

    const ICON = TunIcons;

    const section = (key, title, subtitle, initFn, services) => Layer8SectionConfigs.register(key, {
        title: title, subtitle: subtitle, icon: ICON[key], initFn: initFn,
        modules: [{
            key: key, label: title, icon: ICON[key], isDefault: true,
            services: services.map((s, i) => ({ key: s[0], label: s[1], icon: ICON[s[0]], isDefault: i === 0 }))
        }]
    });

    section('tunnels', 'Tunnels', 'Agents, live tunnels, relays and edge nodes', 'initializeTunTunnels',
        [['agents', 'Agents'], ['live', 'Live'], ['relays', 'Relays'], ['edgenodes', 'Edge nodes']]);
    section('access', 'Access', 'Tokens, reservations, gateway keys and agent certificates', 'initializeTunAccess',
        [['tokens', 'Tokens'], ['reservations', 'Reservations'], ['gwkeys', 'Gateway keys'], ['agentcerts', 'Agent certificates']]);
    section('edge', 'Edge', 'Domains, port forwarding and the router ports', 'initializeTunEdge',
        [['domains', 'Domains'], ['routerports', 'Router ports']]);
    section('alerts', 'Alerts', 'Alert rules and their notifications', 'initializeTunAlerts',
        [['rules', 'Rules'], ['deliveries', 'Delivery log'], ['integrations', 'Integrations']]);
})();
